<?php
require_once __DIR__.'/../includes/bootstrap.php';
$active='abstract-canvass';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf_token();
    try{
        $selected=json_decode((string)($_POST['items_json']??'[]'),true);
        $requestId=(int)($_POST['request_id']??0);$procurementPrNo=trim((string)($_POST['procurement_pr_no']??''));$supplier=trim((string)($_POST['winning_supplier']??''));
        if(!is_array($selected)||!$selected)throw new RuntimeException('Select at least one item from the Abstract of Canvass.');
        if(!$requestId||$procurementPrNo==='')throw new RuntimeException('Enter the Procurement PR No.');
        if($supplier==='')throw new RuntimeException('Select the winning supplier.');
        db()->beginTransaction();$requestIds=[];
        foreach($selected as $line){
            $itemId=(int)($line['id']??0);$quotedCostRaw=trim((string)($line['quoted_cost']??''));$quotedCost=(float)$quotedCostRaw;
            if(!$itemId||$quotedCostRaw===''||!is_numeric($quotedCostRaw)||$quotedCost<0)throw new RuntimeException('Complete the quoted unit price for every selected item.');
            $item=db_one('SELECT id,request_id FROM procurement_request_items WHERE id=? AND procurement_status="AWAITING QUOTATION" FOR UPDATE',[$itemId]);
            if(!$item||(int)$item['request_id']!==$requestId)throw new RuntimeException('A selected item is no longer available in this Abstract of Canvass.');
            db_statement('UPDATE procurement_request_items SET procurement_status="PENDING DELIVERY",winning_supplier=?,quoted_unit_cost=? WHERE id=?',[$supplier,$quotedCost,$itemId]);
            $requestIds[(int)$item['request_id']]=true;
        }
        foreach(array_keys($requestIds) as $processedRequestId){$waiting=(int)db_value('SELECT COUNT(*) FROM procurement_request_items WHERE request_id=? AND procurement_status="AWAITING QUOTATION"',[$processedRequestId]);db_statement('UPDATE procurement_requests SET status=?,procurement_pr_no=? WHERE id=?',[$waiting?'PARTIALLY PROCESSED':'PENDING DELIVERY',$procurementPrNo,$processedRequestId]);}
        db()->commit();set_flash('success',count($selected).' item(s) from the Abstract of Canvass moved to CSSR Inbound.');
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();set_flash('danger',safe_error_message($e));}
    redirect('quoted_items.php');
}
$rows=db_all('SELECT ri.id,ri.request_id,ri.item_description,ri.unit,ri.quantity_requested,ri.unit_cost,r.pr_no,r.procurement_pr_no,p.ppmp_no,d.department_name FROM procurement_request_items ri JOIN procurement_requests r ON r.id=ri.request_id JOIN procurement_ppmp p ON p.id=r.ppmp_id LEFT JOIN departments d ON d.id=r.department_id WHERE ri.procurement_status="AWAITING QUOTATION" ORDER BY r.id DESC,ri.id');
$suppliers=db_all('SELECT supplier_name FROM suppliers WHERE status="Active" ORDER BY supplier_name');$requests=[];
foreach($rows as $row){$requestId=(int)$row['request_id'];if(!isset($requests[$requestId]))$requests[$requestId]=['pr_no'=>$row['pr_no'],'procurement_pr_no'=>$row['procurement_pr_no'],'ppmp_no'=>$row['ppmp_no'],'department_name'=>$row['department_name'],'items'=>[]];$requests[$requestId]['items'][]=$row;}
procurement_header('Abstract of Canvass','abstract-canvass','Select items from each CSSR Purchase Request and record the winning supplier.');
?>
<section class="panel"><div class="panel-head"><h2>Abstract of Canvass</h2><input class="search" id="abstractSearch" placeholder="Search CSSR PR, PPMP, or unit..."></div><div class="table-wrap"><table class="table"><thead><tr><th>CSSR PR No.</th><th>CSSR PPMP No.</th><th>End-User or Implementing Unit</th><th>Available Items</th><th>Action</th></tr></thead><tbody>
<?php foreach($requests as $requestId=>$request):?><tr data-request-row><td><strong><?=e($request['pr_no'])?></strong></td><td><?=e($request['ppmp_no'])?></td><td><?=e($request['department_name']??'')?></td><td><?=count($request['items'])?></td><td><button class="btn" type="button" data-open-abstract="<?=$requestId?>">Open</button></td></tr><?php endforeach;?>
<?php if(!$requests):?><tr><td colspan="5" class="muted">No items are available for the Abstract of Canvass.</td></tr><?php endif;?></tbody></table></div></section>
<?php foreach($requests as $requestId=>$request):?><dialog class="abstract-dialog" id="abstractDialog<?=$requestId?>"><form method="post" class="abstract-form"><?=csrf_field()?><input type="hidden" name="items_json" data-items-json><input type="hidden" name="request_id" value="<?=$requestId?>"><header class="abstract-head"><div><strong>Abstract of Canvass</strong><small><?=e($request['pr_no'])?> · <?=e($request['ppmp_no'])?></small></div><button class="btn light" type="button" data-close-abstract>Close</button></header><div class="abstract-body"><div class="abstract-fields"><label>Procurement PR No. <input class="search" type="text" name="procurement_pr_no" value="<?=e($request['procurement_pr_no']??'')?>" required placeholder="Enter PR number"></label><label>Winning Supplier <select class="search" name="winning_supplier" required><option value="">Select supplier</option><?php foreach($suppliers as $supplier):?><option value="<?=e($supplier['supplier_name'])?>"><?=e($supplier['supplier_name'])?></option><?php endforeach;?></select></label></div><div class="table-wrap"><table class="table"><thead><tr><th>Select</th><th>Item Name</th><th>Unit</th><th>Qty</th><th>Quoted Unit Price</th></tr></thead><tbody>
<?php foreach($request['items'] as $row):?><tr data-item-id="<?=$row['id']?>"><td><input type="checkbox" data-select></td><td><?=e($row['item_description'])?></td><td><?=e($row['unit']??'')?></td><td><?=$row['quantity_requested']?></td><td class="quoted-price-cell"><input class="quoted-price-input" type="number" min="0" step="0.01" placeholder="0.00" data-cost></td></tr><?php endforeach;?></tbody></table></div></div><footer class="abstract-foot"><button class="btn light" type="button" data-close-abstract>Cancel</button><button class="btn green" type="submit">Move Selected to CSSR Inbound</button></footer></form></dialog><?php endforeach;?>
<style>.abstract-dialog{width:min(1180px,96vw);max-height:90vh;padding:0;border:0;border-radius:14px;overflow:auto;background:#fff;box-shadow:0 25px 80px #102b3b66}.abstract-dialog::backdrop{background:#1626347a;backdrop-filter:blur(2px)}.abstract-head,.abstract-foot{position:sticky;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 16px;background:#f0f7fa}.abstract-head{top:0;border-bottom:1px solid #d9e5ed}.abstract-head strong,.abstract-head small{display:block}.abstract-head small{margin-top:3px;color:#647b8a}.abstract-body{padding:16px}.abstract-fields{display:grid;grid-template-columns:repeat(2,minmax(220px,360px));gap:12px;margin-bottom:14px}.abstract-fields label{display:grid;gap:6px;font-weight:700;color:#385568}.abstract-fields .search{width:100%;margin:0}.quoted-price-cell{width:180px}.quoted-price-input{display:block;width:100%;height:32px;margin:0;padding:5px 8px;border:1px solid #9fb3c1;border-radius:6px;background:#fff;color:#18364a;font:inherit;box-sizing:border-box}.quoted-price-input:focus{border-color:#0b668f;outline:2px solid #0b668f22}.abstract-foot{bottom:0;justify-content:flex-end;border-top:1px solid #d9e5ed}@media(max-width:650px){.abstract-fields{grid-template-columns:1fr}.quoted-price-cell{min-width:150px}}</style>
<script>document.getElementById('abstractSearch').oninput=function(){const q=this.value.toLowerCase();document.querySelectorAll('[data-request-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))};document.querySelectorAll('[data-open-abstract]').forEach(button=>button.onclick=()=>document.getElementById('abstractDialog'+button.dataset.openAbstract).showModal());document.querySelectorAll('.abstract-dialog').forEach(dialog=>{dialog.querySelectorAll('[data-close-abstract]').forEach(button=>button.onclick=()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});dialog.querySelector('.abstract-form').onsubmit=event=>{const selected=[...dialog.querySelectorAll('tr[data-item-id]')].filter(row=>row.querySelector('[data-select]').checked).map(row=>({id:Number(row.dataset.itemId),quoted_cost:row.querySelector('[data-cost]').value}));if(!selected.length){event.preventDefault();alert('Select at least one item from the Abstract of Canvass.');return}dialog.querySelector('[data-items-json]').value=JSON.stringify(selected)}});</script>
<?php procurement_footer(); ?>
